async renameVehicle(id: string, name: string, version: string) {
  const previous = cache.vehicle(id);
  cache.patchVehicle(id, { name, sync: 'pending' });

  try {
    const updated = await api.rename(id, name, {
      headers: { 'If-Match': version }
    });
    cache.setVehicle(updated);
    cache.invalidate(['vehicle-search', 'vehicle-summary']);
  } catch (error) {
    cache.setVehicle(previous);
    throw error;
  }
}

